import axios from './axios'
import util from '../common/util.js'

let instance = axios()

let defaultParams = {
  ticket: util.getCache('ticket'),
  'Device-Id': util.getDeviceId(),
  app_version: util.getVersion(),
  // now_lang: util.now_lang,
  app_type: util.checkIos() ? 'ios' : 'android',
  client: 0
}

export default {
  get (url, params, headers) {
    let options = {}
    if (headers) {
      options.headers = headers
    }
    if (!params) {
      params = {}
    }
    if (!defaultParams || !defaultParams.ticket) {
      defaultParams.ticket = util.getCache('ticket')
    }
    options.params = Object.assign(defaultParams, params)
    return instance.get(url, options)
  },
  post (url, params, headers) {
    let options = {}
    if (headers) {
      options.headers = headers
    }
    if (!params) {
      params = {}
    }
    if (!defaultParams.ticket) {
      defaultParams.ticket = util.getCache('ticket')
      defaultParams['Device-Id'] = util.getCache('device') ? util.getCache('device') : 'packapp'
    }
    if (params instanceof FormData) {
      for (let key in defaultParams) {
        params.append(key, defaultParams[key])
      }
    } else {
      let params1 = JSON.parse(JSON.stringify(defaultParams))
      params = Object.assign(params1, params)
    }

    return instance.post(url, params, options)
  }
}
